static void iwp_reset_rx_ring ( iwp_sc_t * sc ) { int n ; iwp_mac_access_enter ( sc , NULL ) ; IWP_WRITE ( sc , FH_MEM_RCSR_CHNL0_CONFIG_REG , 0 ) ; for ( n = 0 ; n < 2000 ; n ++ ) { if ( IWP_READ ( sc , FH_MEM_RSSR_RX_STATUS_REG ) & ( 1 << 24 ) ) { break ; } DELAY ( 1000 ) ; } if ( 2000 == n ) { IWP_DBG ( ( IWP_DEBUG_DMA , "iwp_reset_rx_ring(): " "timeout resetting Rx ring\n" ) ) ; } iwp_mac_access_exit ( sc ) ; sc -> sc_rxq . cur = 0 ; } 